from ovn.client import OVNClient


def test_ovn_insert(ovn_client: OVNClient):
    ovn_client.insert(table="Logical_Switch")


def test_ovn_insert_with_row(ovn_client: OVNClient):
    # _uuid is generated by the database (so the following example is
    # useless)
    # "_uuid": This column, which contains exactly one UUID value, is
    #  initialized to a random value by the database engine when it
    #  creates a row.  It is read-only, and its value never changes
    #  during the lifetime of a row.
    result = ovn_client.insert(
        table="Logical_Switch",
        row={"_uuid": ["uuid", "10000000-36e8-4a4f-8bae-022aec6f6142"]},
    )
    print(result)


def test_ovn_select_all(ovn_client: OVNClient):
    result = ovn_client.select(table="Logical_Switch")
    print(result)


def test_ovn_select_by_uuid(ovn_client: OVNClient):
    # first insert one
    result = ovn_client.insert(table="Logical_Switch")
    uuid = result[0]["uuid"]
    result = ovn_client.select(
        table="Logical_Switch", where=[("_uuid", "==", ("uuid", uuid))]
    )
    assert len(result) == 1, result
    print(result)


def test_ovn_delete_all(ovn_client: OVNClient):
    for record in ovn_client.select(table="Logical_Switch"):
        ovn_client.delete(table="Logical_Switch", uuid=record["_uuid"])
